describe('Async State Preservation During Browser Navigation', () => {
  beforeEach(() => {
    cy.visit('/async-state-test');
  });

  it('should preserve async state when navigating back to the same page', () => {
    // Setup: Load the page with async data
    cy.intercept('GET', '/api/async-data').as('fetchAsyncData');
    cy.wait('@fetchAsyncData');

    // Verify async data is loaded
    cy.get('[data-testid="async-data-value"]').should('be.visible');
    cy.get('[data-testid="async-data-value"]').should('contain', 'Loading...');

    // Navigate to another page
    cy.visit('/another-page');

    // Verify navigation works
    cy.url().should('include', '/another-page');

    // Navigate back to the async state page
    cy.visit('/async-state-test');

    // Verify async state is still preserved
    cy.get('[data-testid="async-data-value"]').should('be.visible');
    cy.get('[data-testid="async-data-value"]').should('contain', 'Loaded');
  });

  it('should preserve async state when navigating to a different page and then back', () => {
    // Setup: Load the page with async data
    cy.intercept('GET', '/api/async-data').as('fetchAsyncData');
    cy.wait('@fetchAsyncData');

    // Verify async data is loaded
    cy.get('[data-testid="async-data-value"]').should('be.visible');
    cy.get('[data-testid="async-data-value"]').should('contain', 'Loading...');

    // Navigate to a different page
    cy.visit('/contact');

    // Verify navigation works
    cy.url().should('include', '/contact');

    // Navigate back to the async state page
    cy.visit('/async-state-test');

    // Verify async state is still preserved
    cy.get('[data-testid="async-data-value"]').should('be.visible');
    cy.get('[data-testid="async-data-value"]').should('contain', 'Loaded');

    // Verify async data is still present after multiple navigations
    cy.get('[data-testid="async-data-value"]').should('contain', 'Loaded');
  });
});
